DROP TABLE IF EXISTS production;

CREATE TABLE production (
    area_code INT,
    area_code_m49 NVARCHAR(10),
    area NVARCHAR(100),
    item_code INT,
    item_code_cpc NVARCHAR(20),
    item NVARCHAR(150),
    element_code INT,
    element NVARCHAR(100),
    unit NVARCHAR(20),
    Y2019 FLOAT,
    Y2020 FLOAT,
    Y2021 FLOAT,
    Y2022 FLOAT,
    Y2023 FLOAT
);

